report+='\n## Program and actual-output inventory\n\nThe following table lists every research program and its actual output files. Counts and elapsed times are recorded in the listed logs; absent timing is reported as not instrumented, not estimated. The detailed sections above state mathematical scope.\n\n| Program | Output or role |\n|---|---|\n'
for p in sorted([*ROOT.rglob('*.py'), *ROOT.rglob('*.js')]):
 if 'sources' in p.parts:continue
 stem=p.stem
 logs=[str(q.relative_to(ROOT)) for q in ROOT.rglob('*') if q.is_file() and 'sources' not in q.parts and q!=p and q.suffix in {'.txt','.json','.log','.tsv'} and (stem in q.stem or stem.replace('check_','') in q.stem)]
 role='; '.join(logs) if logs else 'See associated agent logs; assembly/retrieval tools have no mathematical certificate.'
 report+=f'| `{p.relative_to(ROOT)}` | {role} |\n'
report+='\n## Typesetting verification\n\nThe strict LuaLaTeX build uses missing-glyph errors and records all warnings. A PDF is delivered only after overflow correction and visual inspection. The latest machine-readable QA record, when present, is `logs/pdf_qa.json`; prior failed builds remain in the logs as evidence of corrections.\n'
qa_path=ROOT/'logs/pdf_qa.json'
if qa_path.exists():
 qa=json.loads(qa_path.read_text()); b=qa['before']; a=qa['after']
 report+=f"\nBefore correction: {b['overfull_boxes']} overfull boxes, maximum {b['max_overflow_pt']}pt. After correction: {a['overfull_boxes']} overfull boxes, {a['over_2pt']} exceeding2pt, {a['missing_glyphs']} missing glyphs, {a['undefined_refs']} unresolved references, and {a['bib_warnings']} bibliography warnings. The latest visually reviewed PDF has {qa['pages']} pages. Visual review: {qa['visual_review']}; {len(qa['rendered_pages'])} rendered pages inspected, including every corrected-layout page and a spread sample. The precise page list and PDF/source hashes are in the QA record.\n"
reviews=[]
for p in (ROOT/'logs').glob('review*.json'):
 if re.fullmatch(r'review\d+\.json',p.name):reviews.append(json.loads(p.read_text()))
latest=max(reviews,key=lambda r:r['review']) if reviews else None
if latest and latest.get('stopping_rule_triggered'):
 review_text=(f"The requested stopping rule triggered at scheduled review{latest['review']} "
              f"(recorded {latest['actual_utc']}), after two consecutive scheduled hourly reviews "
              "without qualifying movement. We therefore return this INCOMPLETE final package. "
              "Additional cases, methods, audits and packaging were not counted as progress on the remaining general gates.")
else:
 review_text='No mandatory stopping review has yet authorized a final return.'
report=report.replace('REVIEW_STATUS_PLACEHOLDER',review_text)
assert 'REVIEW_STATUS_PLACEHOLDER' not in report
(ROOT/'RESEARCH_SA20_report.md').write_text(report)
inventory={'original_rows':len(parsed),'unresolved_original_rows':[r[0] for r in parsed if 'unsettled' in r[1].lower()],
           'statement_records':sum(1 for _ in csv.DictReader((ROOT/'RESEARCH_SA20_results.csv').open())),
           'check_events':len((ROOT/'CHECK_EVENTS.tsv').read_text().splitlines())-1,
           'latest_review':latest['review'] if latest else None,
           'stopping_rule_triggered':bool(latest and latest.get('stopping_rule_triggered'))}
(ROOT/'notes/current_inventory.json').write_text(json.dumps(inventory,indent=2)+'\n')
print(f'Wrote {len(parsed)} task/lead rows and report ({len(report)} characters).')
